var age = Math.max(0, +v('age') || 0), life = Math.max(0, +v('life') || 0);
var left = Math.round(Math.max(0, life - age) * 365), total = Math.round(Math.max(life, age) * 365);
if (total < 1) { if (el._crowdStop) el._crowdStop(); el.innerHTML = ''; return; }
left = Math.min(total, left);
Crowd.units(el, { total: total, used: total - left, unit: '日',
title: '一緒に過ごす毎日を玉で並べると',
final: function (l) { return l > 0 ? 'のこり 約' + l.toLocaleString('ja-JP') + '日。今日の散歩も、その中の1日です。' : '想定寿命を過ぎても、一緒にいられる毎日はおまけの宝物です。'; } });
